/**
 * Formatting layer for the result panel.
 *
 * Every string the panel shows is produced here, so the server-rendered HTML
 * and the client-side re-render after a control change cannot drift apart: the
 * island in the page is generated by these same functions.
 *
 * Nothing here computes a radius. See src/lib/effects.ts.
 */
import {
  EFFECT_ROWS,
  citationLine,
  fmtFt,
  fmtKm,
  get,
  interpFt,
} from './effects';
import type { Burst, EffectId, YieldKt } from './effects';

export interface PanelTag {
  t: string;
  c: string;
}

export interface PanelRow {
  id: EffectId;
  name: string;
  sub: string;
  /** radius in kilometres, fixed to 2 dp — the headline number */
  km: string;
  /** radius in feet, or '' for the formula rows */
  ft: string;
  hob: string;
  src: string;
  tags: PanelTag[];
  /** ring radius in km, null when this burst mode has no value for the effect */
  r: number | null;
  color: string;
  /** why the row carries no number in this burst mode */
  absent: string | null;
  checked: boolean;
}

const RING_COLOR: Record<EffectId, string> = {
  fireball: '#ff7a29',
  overpressure_5psi: '#f0b64a',
  overpressure_1psi: '#6fd3a8',
  thermal_2nd: '#7aa7ff',
  thermal_3rd: '#b58cff',
};

const SUB: Record<EffectId, string> = {
  fireball: 'breakaway radius',
  overpressure_5psi: 'peak of the 4 and 6 psi contours, interpolated',
  overpressure_1psi: 'peak of the outermost contour',
  thermal_2nd: '4.5 cal/cm² · light skin, unshaded',
  thermal_3rd: '10 cal/cm² · light skin, unshaded',
};

export const BURST_LABEL: Record<Burst, string> = {
  air: 'Air burst',
  ground: 'Contact burst',
};

const THERMAL_ABSENT =
  'Not reported for a contact burst: Fig. 7.42 is drawn for air bursts at 200·W^0.4 ft, and the manual treats surface-burst thermal radiation by a separate route (§7.41, p. 290).';

export function panelRows(burst: Burst, ykt: YieldKt): PanelRow[] {
  const rows: PanelRow[] = [];

  for (const { id, name } of EFFECT_ROWS) {
    const e = get(id, burst, ykt);
    if (!e) {
      rows.push({
        id, name, sub: SUB[id], km: '—', ft: '', hob: '', src: '',
        tags: [], r: null, color: RING_COLOR[id],
        absent: THERMAL_ABSENT, checked: false,
      });
      continue;
    }

    const ip = interpFt(e);
    const tags: PanelTag[] = [];

    if (e.effect === 'fireball') {
      tags.push({ t: 'printed equation, not a chart reading', c: 'tag-plain' });
    }
    if (e.scaled && e.scaled_label) {
      tags.push({ t: e.scaled_label, c: 'tag-scaled' });
    }
    if (ip) {
      tags.push({
        t: `interpolated between 4 and 6 psi contours, at ${fmtFt(Number(ip))} ft (1 kt)`,
        c: 'tag-warn',
      });
    }
    if (e.value_type === 'curve_read') {
      tags.push({ t: 'read directly off Fig. 7.42, not scaled', c: 'tag-read' });
    }
    if (e.q_cal_cm2 !== undefined) {
      tags.push({ t: `${e.q_cal_cm2} cal/cm² · light skin, unshaded`, c: 'tag-plain' });
    }
    if (e.burst === 'air' && e.hob_ft !== null && e.hob_ft > 5000) {
      tags.push({
        t: `burst height ${fmtFt(e.hob_ft)} ft is beyond the manual's 5,000 ft homogeneous-atmosphere assumption`,
        c: 'tag-warn',
      });
    }

    let hob: string;
    if (e.effect === 'fireball') {
      hob = burst === 'air'
        ? 'printed equation · no burst height input'
        : 'contact burst · height of burst = 0';
    } else if (e.effect.startsWith('thermal')) {
      hob = `burst height ${fmtFt(e.hob_ft ?? 0)} ft · 200·W^0.4 (§7.42)`;
    } else if (burst === 'ground') {
      hob = 'contact burst · height of burst = 0';
    } else {
      hob = `burst height ${fmtFt(e.hob_ft ?? 0)} ft`;
    }

    rows.push({
      id, name, sub: SUB[id],
      km: fmtKm(e.radius_km),
      ft: e.radius_ft !== null ? fmtFt(e.radius_ft) : '',
      hob,
      src: citationLine(e),
      tags,
      r: e.radius_km,
      color: RING_COLOR[id],
      absent: null,
      checked: e.checked_by !== null,
    });
  }

  return rows;
}

/** Largest ring in the set — the drawing is scaled so it always fits. */
export function maxRing(rows: PanelRow[]): number {
  return rows.reduce((m, row) => (row.r !== null && row.r > m ? row.r : m), 0);
}

/**
 * Ring geometry. One SVG user unit is 1 km at scale 1; the group is scaled so the
 * widest ring lands on 92 units inside a 240-unit viewBox.
 */
export const RING_TARGET = 92;

export function ringScale(rows: PanelRow[]): number {
  const m = maxRing(rows);
  return m > 0 ? RING_TARGET / m : 1;
}

/** A round-number scale bar whose drawn length stays between 30 and 84 units. */
export function scaleBar(rows: PanelRow[]): { km: number; units: number } {
  const s = ringScale(rows);
  const steps = [1, 2, 5, 10, 20, 25, 50, 100, 200, 500];
  let pick = steps[0];
  for (const st of steps) {
    if (st * s <= 84) pick = st;
  }
  return { km: pick, units: Math.round(pick * s * 10) / 10 };
}
